import { JSDOM } from 'jsdom';
import * as crypto from 'crypto';

// Circuit Breaker States
enum CircuitState {
  CLOSED = 'CLOSED',
  OPEN = 'OPEN',
  HALF_OPEN = 'HALF_OPEN'
}

interface CircuitBreakerConfig {
  failureThreshold: number;
  recoveryTimeout: number;
  halfOpenRequests: number;
}

class CircuitBreaker {
  private state: CircuitState = CircuitState.CLOSED;
  private failureCount: number = 0;
  private lastFailureTime: number = 0;
  private config: CircuitBreakerConfig;

  constructor(config: CircuitBreakerConfig) {
    this.config = config;
  }

  canExecute(): boolean {
    if (this.state === CircuitState.CLOSED) return true;
    if (this.state === CircuitState.OPEN) {
      const elapsed = Date.now() - this.lastFailureTime;
      if (elapsed >= this.config.recoveryTimeout) {
        this.state = CircuitState.HALF_OPEN;
        return true;
      }
      return false;
    }
    return this.failureCount < this.config.halfOpenRequests;
  }

  recordSuccess(): void {
    this.failureCount = 0;
    this.state = CircuitState.CLOSED;
  }

  recordFailure(): void {
    this.failureCount++;
    this.lastFailureTime = Date.now();
    if (this.failureCount >= this.config.failureThreshold) {
      this.state = CircuitState.OPEN;
    }
  }

  getState(): CircuitState {
    return this.state;
  }
}

// Template registry with content-hash verification
interface TemplateEntry {
  content: string;
  hash: string;
  trusted: boolean;
}

class TemplateRegistry {
  private templates: Map<string, TemplateEntry> = new Map();

  register(name: string, content: string, trusted: boolean = false): void {
    const hash = crypto.createHash('sha256').update(content).digest('hex');
    this.templates.set(name, { content, hash, trusted });
  }

  get(name: string): TemplateEntry | undefined {
    return this.templates.get(name);
  }

  verifyIntegrity(name: string): boolean {
    const entry = this.templates.get(name);
    if (!entry) return false;
    const currentHash = crypto.createHash('sha256').update(entry.content).digest('hex');
    return currentHash === entry.hash;
  }
}

// Sanitization layer
class ContentSanitizer {
  private static readonly DANGEROUS_TAGS = ['script', 'iframe', 'object', 'embed', 'link'];
  private static readonly DANGEROUS_ATTRS = ['onerror', 'onload', 'onclick', 'onmouseover'];

  static sanitizeForPdf(input: string): string {
    let sanitized = input;
    for (const tag of this.DANGEROUS_TAGS) {
      const regex = new RegExp(`<${tag}[^>]*>.*?</${tag}>`, 'gi');
      sanitized = sanitized.replace(regex, '');
    }
    for (const attr of this.DANGEROUS_ATTRS) {
      const regex = new RegExp(`${attr}\\s*=\\s*["'][^"']*["']`, 'gi');
      sanitized = sanitized.replace(regex, '');
    }
    return sanitized;
  }

  static escapeHtmlEntities(input: string): string {
    return input
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#x27;');
  }
}

// PDF content renderer using DOM manipulation
class PdfContentRenderer {
  private dom: JSDOM;
  private circuitBreaker: CircuitBreaker;
  private templateRegistry: TemplateRegistry;

  constructor() {
    this.dom = new JSDOM('<!DOCTYPE html><html><body></body></html>');
    this.circuitBreaker = new CircuitBreaker({
      failureThreshold: 3,
      recoveryTimeout: 30000,
      halfOpenRequests: 1
    });
    this.templateRegistry = new TemplateRegistry();
    this.initializeDefaultTemplates();
  }

  private initializeDefaultTemplates(): void {
    this.templateRegistry.register('header', '<div class="header">{{title}}</div>', true);
    this.templateRegistry.register('body', '<div class="content">{{body}}</div>', true);
    this.templateRegistry.register('footer', '<div class="footer">{{footer}}</div>', true);
  }

  private interpolateTemplate(template: string, variables: Record<string, string>, trusted: boolean): string {
    return template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
      const value = variables[key];
      if (value === undefined) return match;
      // For trusted templates, we apply sanitization to variable values
      // For untrusted content, we escape everything
      if (trusted) {
        return ContentSanitizer.sanitizeForPdf(value);
      }
      return ContentSanitizer.escapeHtmlEntities(value);
    });
  }

  renderSection(templateName: string, variables: Record<string, string>): string {
    if (!this.circuitBreaker.canExecute()) {
      throw new Error('Circuit breaker is open - PDF rendering temporarily unavailable');
    }

    try {
      const entry = this.templateRegistry.get(templateName);
      if (!entry) {
        throw new Error(`Template '${templateName}' not found`);
      }

      if (!this.templateRegistry.verifyIntegrity(templateName)) {
        throw new Error(`Template '${templateName}' integrity check failed`);
      }

      const rendered = this.interpolateTemplate(entry.content, variables, entry.trusted);
      this.circuitBreaker.recordSuccess();
      return rendered;
    } catch (error) {
      this.circuitBreaker.recordFailure();
      throw error;
    }
  }

  registerCustomTemplate(name: string, content: string): void {
    // Custom templates are never trusted
    this.templateRegistry.register(name, content, false);
  }

  generatePdfHtml(sections: Array<{ template: string; vars: Record<string, string> }>): string {
    const document = this.dom.window.document;
    const container = document.createElement('div');
    container.setAttribute('id', 'pdf-root');

    for (const section of sections) {
      const rendered = this.renderSection(section.template, section.vars);
      const sectionEl = document.createElement('section');
      sectionEl.innerHTML = rendered;
      container.appendChild(sectionEl);
    }

    return container.innerHTML;
  }
}

export { PdfContentRenderer, CircuitBreaker, TemplateRegistry, ContentSanitizer, CircuitState };
